from lib import *
K="חלק ה׳ · קרחונים"
def pages():
    P=[]
    P.append(page(5,K,"איך נולד קרחון","How a glacier forms and flows",
    hero=sf("glacier_section","<b>חתך אורך סכמטי של קרחון עמק.</b> בקצה העליון נצבר שלג; מתחת לקו שיווי המסה (ELA) הקרח נמס. בין שני האזורים הקרח זורם כלפי מטה. האיור סכמטי, ללא קנה מידה.",""),
    cols=f'''
<p><b>קרחון</b> הוא גוש קרח רב-שנתי, שנוצר מצבירת שלג ונע בכוח משקלו. כדי שיתהווה קרחון, צריך ששלג שנוסף בחורף לא יימס כולו בקיץ במשך שנים רבות. השלג הנצבר נדחס בהדרגה: עם הזמן הוא שוקע, מתגבש מחדש, ואוויר נדחס החוצה.</p>
<h2>משלג לקרח</h2>
{sf("densify","<b>התפתחות הצפיפות</b> (ק״ג/מ״ק) משלג לקרח קרחוני. בקרחונים ממוזגים התהליך נמשך שנים ספורות; בקרחונים קרים (אנטארקטיקה) מאות עד אלפי שנים.")}
<p><b>שלג</b> טרי צפיפותו 50 עד 100 ק״ג/מ״ק. <b>שלג ישן</b> או <b>שלוגית</b> (firn, ״פירן״) הוא שלג שעבר לפחות קיץ אחד ונדחס לצפיפות 400 עד 830 ק״ג/מ״ק. כשהצפיפות מגיעה לכ-830, הנקבוביות נסגרות ונוצר <b>קרח קרחוני</b> (עד כ-917 ק״ג/מ״ק), מבודד בבועות אוויר סגורות. הבדל מוחשי: שלג הוא חומר גרגירי ופורוזיבי, וקרח קרחוני הוא סלע מטמורפי, מוצק וגבישי.</p>
<h2>מאזן מסה</h2>
<p>גודל הקרחון נקבע ב<b>מאזן המסה</b>: צבירה (שלג, שלג נסחף, מפולות) פחות הפשרה והתאדות. מקובל למדוד במטרים של שווה-ערך-מים בשנה. <b>אזור הצבירה</b> נמצא בחלק העליון, שבו מצטבר יותר ממה שנמס; <b>אזור ההפשרה</b> נמצא בחלק התחתון. הגבול ביניהם הוא <b>קו שיווי המסה</b> (<span class='lat'>equilibrium-line altitude, ELA</span>). בקרחון במצב מאוזן, אזור הצבירה מהווה כ-60 עד 70 אחוז משטח הקרחון. כשה-ELA עולה בעקבות התחממות, אזור ההפשרה מתרחב והקרחון מצטמק.</p>
{sf("mass_balance","<b>מאזן מסה כפונקציה של גובה</b> (סכמטי). מעל ה-ELA מאזן חיובי (עודף), מתחתיו שלילי (גירעון). השטחים הצבועים מייצגים את המאזן.")}
<h2>איך הקרח נע</h2>
<p>קרח זורם בשני מנגנונים: <b>עיוות פנימי</b> (הגבישים נפתלים זה על זה תחת עומס; לפי <b>חוק גלן</b> קצב העיוות עולה בעוצמה שלישית בקירוב של הלחץ) ו<b>החלקה על המצע</b> כשיש שכבת מים בבסיס. בקרחוני עמק ממוזגים המהירות היא עשרות מטרים בשנה; קרחונים ״מהירים״, כמו יעקבסהבן בגרינלנד, זורמים כ-40 מ׳ ביום. בחלק העליון הקרח שביר ויוצר <b>סדקים</b>, בעומק כ-30 עד 40 מ׳; מתחתיו הוא פלסטי.</p>
{box("data","סוגי קרחונים לפי טמפרטורה","<p><b>ממוזג</b> (temperate): הקרח בנקודת הפשרה, יש מים בבסיס, שחיקה גבוהה (האלפים, ניו זילנד, אלסקה). <b>קר</b> (cold): קפוא למצע, שחיקה נמוכה (אנטארקטיקה, גרינלנד). <b>פוליתרמי</b>: חלק כך וחלק כך (קנדה הארקטית, סבאלברד).</p>")}
''',toc="איך נולד קרחון"))
    P.append(page(5,K,"נופי קרח: צורות, סוגים ונסיגה","Glacial landscapes, glacier types and retreat",
    hero=sf("glacial_landforms","<b>נוף קרחוני במבט על</b> (סכמטי): קרקסים, ארטים, קרן, קרחון עמק, מורנות, אגם קרחוני ומישור שטפונות. תצורות אלה נראות בהרי האלפים, הרוקי, סן חואן, סיירה נבדה וניו זילנד.",""),
    cols=f'''
<h2>איך קרח מפסל</h2>
<p>קרח מפסל בשני תהליכים: <b>שחיקה</b> (אבנים שנתפסו בקרח משרטטות את המצע ויוצרות קרקע מלוטשת וחתימות) ו<b>עקירה</b> (plucking: הקרח קופא לסדקי הסלע ועוקר גושים). התוצאה: <b>קרקס</b> (שקע בצורת כורסה, בראש העמק), ולעיתים אגם בתוכו (<b>טארן</b>); כששני קרקסים נפגשים נוצר <b>ארט</b> (רכס חד), וכשכמה קרקסים חותכים פסגה מכל כיוון נוצרת <b>קרן</b> (horn), כמו המטרהורן וסנפלס. בעמק: <b>חתך U</b>, <b>עמקים תלויים</b> עם מפלים, ובחוף: <b>פיורדים</b>, שבהם הים מציף עמק קרחוני (סוגנפיורד, כ-1,300 מ׳ עומק).</p>
<p>הקרח גם מפקיד: <b>מורנות</b> (צדדיות, אמצעיות וקצה) הן ערמות של סלעים וחצץ שהקרח נשא; <b>סלעים נודדים</b> (erratics) הם גושים שנשאו עשרות או מאות ק״מ; <b>מישור שטפונות</b> (sandur) הוא חול ומים בחזית הקרחון; ו<b>דרמלינים</b> (גבעות מוארכות) בחלק הנוף שבו כיסה הקרח שטחים עצומים.</p>
<h2>ארבעה סוגי קרחונים</h2>
{table([["קרחון אלפיני / עמק","האלפים, הרוקי, ניו זילנד","עשרות ק״מ ומטה; בעמק או קרקס"],["שדה קרח (icefield)","קולומביה, ג׳ונו","מכסה רכס; קרחונים יוצאים ממנו"],["כיפת קרח (ice cap)","וטנאיוקול (~7,700 קמ״ר)","פחות מ-50,000 קמ״ר; כיפה"],["יריעת קרח (ice sheet)","גרינלנד (~1.7 מיליון), אנטארקטיקה (~14 מיליון קמ״ר)","יותר מ-50,000 קמ״ר"]],["סוג","דוגמאות","הערות"])}
<p>הגבול בין <b>שדה קרח</b> ל<b>כיפת קרח</b> הוא נוף: בשדה הקרח הקרח עוקב אחרי הטופוגרפיה שמתחתיו; בכיפה הוא יוצר כיפה אחידה שאינה קשורה לנוף. יריעות הקרח מכילות כ-99 אחוז מהקרח ביבשה: אנטארקטיקה כ-58 מ׳ ושווה-ערך-מפלס-ים, וגרינלנד כ-7 מ׳.</p>
{box("compare","קרחונים באלפים לעומת צפון אמריקה","<p>באלפים: קרחונים רבים וקטנים (כ-1,800 קמ״ר בתחילת שנות ה-2000), ממוזגים, במצב נסיגה מהירה (שוויץ: כ-6 אחוז מהנפח ב-2022 וכ-4 ב-2023). בצפון אמריקה: אלסקה לבדה כ-87,000 קמ״ר (RGI 6.0), קרחוני ענק (מלספינה, קהילטנה) וקרחוני ים; ברוקי של ארצות הברית רק מאות קרחונים קטנים. ההבדל נובע מגודל ההרים, מקרבה לאוקיינוס ומקו הרוחב.</p>")}
<h2>נסיגה ושינוי אקלים</h2>
<p>לפי Hugonnet ועמיתיו (2021), קרחוני העולם, מחוץ ליריעות הקרח, איבדו כ-267 מיליארד טונות קרח בשנה בין 2000 ל-2019, והקצב התגבר בעשור האחרון. קרחונים תרמו כ-0.74 מ״מ בשנה לעליית פני הים, כחמישית מהעלייה הנצפית. הקרחונים נעלמים בקצב שתלוי בפליטות; אלה הנמוכים והדרומיים נעלמים ראשונים. נסיגה משנה נהרות, מעלה סכנות של מפולות ושטפונות אגמי קרחון (GLOF), ומחשפת נוף חדש: אגמים וצמחייה צעירה.</p>
<p>שלג וקרח משמשים כ״מדחום״ של כדור הארץ: ההרים הם מהאזורים שבהם שינוי האקלים נראה לעין מוקדם. היעלמות קרחון בן אלפי שנים אינה רק אובדן נוף אלא שינוי באספקת המים ובבתי הגידול של מאות מיליוני בני אדם ושל מינים רבים.</p>
''',toc="נופי קרח, סוגים ונסיגה"))
    return P
